INSERT INTO [dbo].[Manga] ([Id],[Name],[Description],[Level],[Status],[Type],[Countries],[Season],[MangaSeasonId],[UserId],[CreateDate],[IdUserCreate],[UpdateDate],[IdUserUpdate],[DeleteDate],[IdUserDelete]) VALUES (N'e7b5e9a0-f83d-4477-9a17-18b73bf37dd1',N'One Punch-Man',N'After rigorously training for three years, the ordinary Saitama has gained immense strength which allows him to take out anyone and anything with just one punch. He decides to put his new skill to good use by becoming a hero. However, he quickly becomes bored with easily defeating monsters, and wants someone to give him a challenge to bring back the spark of being a hero.
