INSERT INTO [dbo].[Manga] ([Id],[Name],[Description],[Level],[Status],[Type],[Countries],[Season],[MangaSeasonId],[UserId],[CreateDate],[IdUserCreate],[UpdateDate],[IdUserUpdate],[DeleteDate],[IdUserDelete]) VALUES (N'6fd78c0f-151f-4b0c-9fcc-e8536ee860d0',N'Naruto',N'Whenever Naruto Uzumaki proclaims that he will someday become the Hokage—a title bestowed upon the best ninja in the Village Hidden in the Leaves—no one takes him seriously. Since birth, Naruto has been shunned and ridiculed by his fellow villagers. But their contempt isn''t because Naruto is loud-mouthed, mischievous, or because of his ineptitude in the ninja arts, but because there is a demon inside him. Prior to Naruto''s birth, the powerful and deadly Nine-Tailed Fox attacked the village. In order to stop the rampage, the Fourth Hokage sacrificed his life to seal the demon inside the body of the newborn Naruto.
