INSERT INTO [dbo].[Manga] ([Id],[Name],[Description],[Level],[Status],[Type],[Countries],[Season],[MangaSeasonId],[UserId],[CreateDate],[IdUserCreate],[UpdateDate],[IdUserUpdate],[DeleteDate],[IdUserDelete]) VALUES (N'416f4c23-67f4-48e2-9cd4-6fe61edd520c',N'Spy x Family',N'For the agent known as "Twilight," no order is too tall if it is for the sake of peace. Operating as Westalis'' master spy, Twilight works tirelessly to prevent extremists from sparking a war with neighboring country Ostania. For his latest mission, he must investigate Ostanian politician Donovan Desmond by infiltrating his son''s school: the prestigious Eden Academy. Thus, the agent faces the most difficult task of his career: get married, have a child, and play family.
